#!/usr/bin/env python3
"""Apply NexusOps AI password security features with backups."""
import base64
import os
import shutil
import sys
from datetime import datetime

FILES = {'backend/database.py': '', 'backend/main.py': '', 'frontend/src/App.jsx': '', 'frontend/src/App.css': ''}
REQUIRED = ["backend/main.py", "backend/database.py", "frontend/src/App.jsx", "frontend/src/App.css"]
root = os.path.abspath(os.getcwd())
missing = [p for p in REQUIRED if not os.path.isfile(os.path.join(root, p))]
if missing:
    print("ERROR: Run this script from the NexusOps-AI project root.")
    print("Missing: " + ", ".join(missing))
    sys.exit(1)

stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
for rel, encoded in FILES.items():
    target = os.path.join(root, rel)
    backup = target + ".before-password-security"
    if os.path.exists(target):
        if not os.path.exists(backup):
            shutil.copy2(target, backup)
        else:
            shutil.copy2(target, target + ".before-password-security-" + stamp)
    with open(target, "wb") as handle:
        handle.write(base64.b64decode(encoded.encode("ascii")))
    print("Updated:", rel)

# This local development app has no email provider configured. Explicitly enable
# token display for local testing; turn this off before any public deployment.
env_path = os.path.join(root, "backend", ".env")
if os.path.isfile(env_path):
    with open(env_path, "r", encoding="utf-8") as f:
        env_text = f.read()
    if "RESET_PASSWORD_DEV_MODE=" not in env_text:
        shutil.copy2(env_path, env_path + ".before-password-security")
        with open(env_path, "a", encoding="utf-8") as f:
            if env_text and not env_text.endswith("\n"):
                f.write("\n")
            f.write("\n# Local-only: show reset tokens because SMTP/email is not configured\nRESET_PASSWORD_DEV_MODE=true\n")
        print("Updated: backend/.env (local reset-token mode enabled)")
    else:
        print("Kept existing RESET_PASSWORD_DEV_MODE setting in backend/.env")
else:
    print("WARNING: backend/.env not found; add RESET_PASSWORD_DEV_MODE=true for local reset-token testing.")

print("\nSUCCESS: password change, forgot-password, reset-password, and session revocation installed.")
print("Backups were saved beside original files.")
print("LOCAL DEVELOPMENT ONLY: reset tokens are shown in the UI when RESET_PASSWORD_DEV_MODE=true.")
print("Disable that setting and configure email delivery before exposing this app publicly.")
